/**
 * Copies employee-agent.exe into src-tauri/resources for NSIS bundling.
 * Fails the build if the agent binary is missing (no misleading installer).
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { createHash } from 'crypto';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const candidates = [
  path.join(root, 'target-employee-agent', 'release', 'employee-agent.exe'),
  path.join(root, 'employee-agent', 'target', 'release', 'employee-agent.exe'),
  path.join(root, 'release', 'employee-agent-windows', 'employee-agent.exe'),
];

const src = candidates.find((p) => fs.existsSync(p));
if (!src) {
  console.error('BLOCKER: employee-agent.exe not found. Build employee-agent first:');
  console.error('  cd employee-agent && cargo build --release');
  console.error('Expected one of:');
  candidates.forEach((c) => console.error('  -', c));
  process.exit(1);
}

const destDir = path.join(root, 'src-tauri', 'resources', 'agent');
fs.mkdirSync(destDir, { recursive: true });
const dest = path.join(destDir, 'employee-agent.exe');
fs.copyFileSync(src, dest);

const buf = fs.readFileSync(dest);
const sha = createHash('sha256').update(buf).digest('hex');
const meta = {
  source: src,
  dest,
  size_bytes: buf.length,
  sha256: sha,
  bundled_at: new Date().toISOString(),
  version: '0.1.0',
};
fs.writeFileSync(path.join(destDir, 'agent-manifest.json'), JSON.stringify(meta, null, 2));

// Non-secret template only (no service role / no fixed employee id)
const envTemplate = `# Generated by prepare-agent-bundle — employee id filled at first authorized sign-in
SUPABASE_URL=
SUPABASE_ANON_KEY=
EMPLOYEE_ID=
SCREENSHOT_INTERVAL_SECONDS=60
HEARTBEAT_INTERVAL_SECONDS=30
SCREENSHOT_QUALITY=70
OFFICE_HOURS_ENABLED=true
`;
fs.writeFileSync(path.join(destDir, 'agent.env.template'), envTemplate);

console.log('Bundled agent OK');
console.log('  from:', src);
console.log('  to:  ', dest);
console.log('  size:', buf.length, 'bytes');
console.log('  sha256:', sha);
